// 解析 DeepSeek 返回的 JSON 创意
const raw = $input.first().json.choices?.[0]?.message?.content || '';

let idea = null;
try {
  // 清理可能的代码块标记
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);
  idea = Array.isArray(parsed) ? parsed[0] : parsed;
} catch(e) {
  console.error('JSON解析失败:', e.message, '原始内容:', raw);
  // 降级处理
  idea = {
    Caption: '精彩瞬间来了！ 🎬 #viral #trending #video #ai #shortfilm #fyp #foryou #explore #aiart #creative #shorts #reels',
    Idea: '一只北极熊在冰川上自拍',
    Environment: '北极冰川，冷色调，纪录片风格',
    Status: 'for production'
  };
}

console.log('解析到创意:', idea.Idea);

return [{ json: {
  output: [idea],
  idea_text: idea.Idea,
  caption: idea.Caption,
  environment: idea.Environment,
  status: idea.Status
}}];

