// 整理飞书多维表格返回的记录，方便后续节点引用
const items = $input.first().json.data?.items || [];
if (!items.length) {
  throw new Error('没有找到待发布的视频记录，请检查多维表格数据');
}
const record = items[0];
const fields = record.fields || {};

return [{ json: {
  record_id: record.record_id,
  final_output: fields.final_output || '',
  DESCRIPTION: fields.caption || '',
  Titre: fields.idea || '',
  idea: fields.idea || '',
  caption: fields.caption || ''
}}];

